// =============================================================================
// Node: "Bounded Sampler"            (Code node - Run Once for All Items)
// -----------------------------------------------------------------------------
// Input : output of "Parse JSON File" -> one item whose json.data is the array
//         of sessions from data/mock_transcripts.json. (Also tolerates one item
//         per session, in case the file is fed in a different way.)
// Output: ONE item per session, carrying
//           - the full session (needed later by the dual-stream parser)
//           - a bounded sample: first 40 turns + last 20 turns
//           - a ready-to-send Ollama /api/chat request for the classifier
// =============================================================================

const HEAD_TURNS = 40;
const TAIL_TURNS = 20;
const LLM_MODEL = $env.LLM_MODEL || 'llama3.2';

// ---- 1. Collect sessions regardless of how the file was unwrapped ----------
const sessions = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  if (Array.isArray(j.data)) sessions.push(...j.data);
  else if (Array.isArray(j.sessions)) sessions.push(...j.sessions);
  else if (Array.isArray(j.transcript)) sessions.push(j);
}

if (sessions.length === 0) {
  throw new Error('Bounded Sampler: no sessions found. Expected a JSON array of sessions with a "transcript" array.');
}

// ---- 2. Helpers -------------------------------------------------------------
/**
 * First HEAD + last TAIL turns. If the transcript is short enough that the two
 * windows would overlap, the whole transcript is returned once (no duplicates).
 */
function boundedSample(turns, head = HEAD_TURNS, tail = TAIL_TURNS) {
  if (turns.length <= head + tail) {
    return { turns: turns.slice(), truncated: false, omitted: 0 };
  }
  return {
    turns: [...turns.slice(0, head), ...turns.slice(-tail)],
    truncated: true,
    omitted: turns.length - head - tail,
  };
}

function roleOf(speaker, participants) {
  const p = participants.find((x) => x.name === speaker);
  if (!p) return 'unknown';
  return p.is_team_member ? 'GenX team member' : 'external guest';
}

function renderTurns(turns, participants, truncated, omitted) {
  const lines = [];
  turns.forEach((t, i) => {
    if (truncated && i === HEAD_TURNS) lines.push(`... [${omitted} middle turns omitted] ...`);
    lines.push(`[${t.timestamp ?? '--:--:--'}] ${t.speaker} (${roleOf(t.speaker, participants)}): ${String(t.text ?? '').trim()}`);
  });
  return lines.join('\n');
}

// ---- 3. Classifier prompt (strict JSON via Ollama structured outputs) ------
const CLASSIFIER_SYSTEM = [
  'You are the ingestion gatekeeper for the GenX Leadership Academy coaching knowledge base.',
  'Read the meeting sample and decide which kind of meeting it is.',
  '',
  'Categories:',
  '- "Client Coaching": a coach works with an external client on leadership, wellbeing, delegation, team dynamics, feedback or personal performance.',
  '- "Internal Operations": GenX team members talk among themselves about engineering, tooling, CRM, sprints, deployments, admin or internal process.',
  '- "Sales Discovery": a conversation about buying coaching services: pricing, budget, retainers, contracts, pilots, proposals or scope of work.',
  '- "Other": anything else, or not enough signal to decide.',
  '',
  'confidence_score is your probability (0.0 to 1.0) that meeting_type is correct.',
  'summary is one or two sentences describing what the meeting was about.',
  'Answer with a single JSON object: {"meeting_type": "...", "confidence_score": 0.0, "summary": "..."}',
].join('\n');

const CLASSIFIER_SCHEMA = {
  type: 'object',
  properties: {
    meeting_type: {
      type: 'string',
      enum: ['Client Coaching', 'Internal Operations', 'Sales Discovery', 'Other'],
    },
    confidence_score: { type: 'number' },
    summary: { type: 'string' },
  },
  required: ['meeting_type', 'confidence_score', 'summary'],
};

// ---- 4. Emit one item per session --------------------------------------------
return sessions.map((s) => {
  const participants = Array.isArray(s.participants) ? s.participants : [];
  const transcript = Array.isArray(s.transcript) ? s.transcript : [];
  const sample = boundedSample(transcript);
  const sampleText = renderTurns(sample.turns, participants, sample.truncated, sample.omitted);

  const participantLine = participants
    .map((p) => `${p.name} (${p.is_team_member ? 'GenX team member' : 'external guest'})`)
    .join(', ');

  return {
    json: {
      session_id: s.id,
      title: s.title ?? '',
      source_created_at: s.created_at ?? null,
      participants,
      transcript,
      turn_count: transcript.length,
      sample_turn_count: sample.turns.length,
      sample_truncated: sample.truncated,
      sample_text: sampleText,
      classifier_request: {
        model: LLM_MODEL,
        stream: false,
        format: CLASSIFIER_SCHEMA,
        options: { temperature: 0 },
        messages: [
          { role: 'system', content: CLASSIFIER_SYSTEM },
          {
            role: 'user',
            content: `Meeting title: ${s.title ?? '(none)'}\nParticipants: ${participantLine}\n\nTranscript sample (${sample.turns.length} of ${transcript.length} turns):\n${sampleText}`,
          },
        ],
      },
    },
  };
});

// =============================================================================
// Node: "Parse & Validate Classification"   (Code node - Run Once for All Items)
// -----------------------------------------------------------------------------
// Input : responses of the "Classification Agent" HTTP node (Ollama /api/chat).
//         That node has "On Error: Continue", so an item may be an error object.
// Output: the original session + a normalised, always-valid classification:
//           meeting_type     one of the 4 allowed labels
//           confidence_score number clamped to [0, 1]
//           summary          string
//         Anything malformed degrades to { "Other", 0 } -> it gets ARCHIVED,
//         never ingested. The gate fails closed.
// =============================================================================

const ALLOWED = ['Client Coaching', 'Internal Operations', 'Sales Discovery', 'Other'];

/** Pull the first JSON object out of an LLM reply (handles ```json fences / chatter). */
function extractJson(raw) {
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw !== 'string' || !raw.trim()) return null;
  const text = raw.replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(text); } catch (_) { /* fall through */ }
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (_) { return null; }
}

/** Map near-misses ("client coaching session", "SALES") onto the allowed labels. */
function normaliseType(value) {
  const v = String(value ?? '').toLowerCase().trim();
  const exact = ALLOWED.find((a) => a.toLowerCase() === v);
  if (exact) return exact;
  if (v.includes('coach')) return 'Client Coaching';
  if (v.includes('internal') || v.includes('operation')) return 'Internal Operations';
  if (v.includes('sales') || v.includes('discovery')) return 'Sales Discovery';
  return 'Other';
}

/** Accept 0.92, "0.92", "92%", 92 -> 0.92. Garbage -> 0. */
function normaliseConfidence(value) {
  let n = typeof value === 'string' ? parseFloat(value.replace('%', '')) : Number(value);
  if (!Number.isFinite(n)) return 0;
  if (n > 1 && n <= 100) n = n / 100;
  return Math.min(1, Math.max(0, Math.round(n * 1000) / 1000));
}

const out = [];
$input.all().forEach((item, i) => {
  const session = $('Bounded Sampler').itemMatching(i).json;
  const res = item.json ?? {};

  const raw = res?.message?.content ?? res?.response ?? null;
  const parsed = res.error ? null : extractJson(raw);

  let classification;
  if (parsed && typeof parsed === 'object') {
    classification = {
      meeting_type: normaliseType(parsed.meeting_type),
      confidence_score: normaliseConfidence(parsed.confidence_score),
      summary: String(parsed.summary ?? '').trim(),
      parse_ok: true,
    };
  } else {
    classification = {
      meeting_type: 'Other',
      confidence_score: 0,
      summary: '',
      parse_ok: false,
      parse_error: res.error ? `LLM call failed: ${res.error.message ?? JSON.stringify(res.error)}` : 'Could not parse classifier output as JSON',
    };
  }

  // Drop the large request payload, keep everything the next nodes need.
  const { classifier_request, ...rest } = session;
  out.push({
    json: {
      ...rest,
      ...classification,
      classifier_raw: typeof raw === 'string' ? raw : JSON.stringify(raw ?? res),
    },
    pairedItem: { item: i },
  });
});

return out;

// =============================================================================
// Node: "Prepare Archive Row"        (Code node - Run Once for All Items)
// -----------------------------------------------------------------------------
// Receives every session the Ingestion Gate rejected (Internal Operations,
// Sales Discovery, Other, or Client Coaching below the 0.80 confidence bar)
// and shapes it into a flat relational row. No embedding is ever computed here.
// =============================================================================

const MIN_CONFIDENCE = 0.8;

return $input.all().map((item) => {
  const s = item.json;
  const reason = s.meeting_type === 'Client Coaching'
    ? `low_confidence (${s.confidence_score} < ${MIN_CONFIDENCE})`
    : `classified_as_${s.meeting_type.toLowerCase().replace(/\s+/g, '_')}`;

  return {
    json: {
      session_id: s.session_id,
      title: s.title,
      source_created_at: s.source_created_at,
      meeting_type: s.meeting_type,
      confidence_score: s.confidence_score,
      summary: s.summary,
      reject_reason: s.parse_ok === false ? `unparseable_classification: ${s.parse_error}` : reason,
      participants_json: JSON.stringify(s.participants ?? []),
      transcript_json: JSON.stringify(s.transcript ?? []),
      classifier_raw: s.classifier_raw ?? null,
    },
  };
});

// =============================================================================
// Node: "Prepare Framework Distillation"   (Code node - Run Once for All Items)
// -----------------------------------------------------------------------------
// For every APPROVED coaching session, build an Ollama /api/chat request that
// condenses the full transcript into a dense framework note (Stream 1).
// The note follows a fixed, positively-phrased template, including a
// "Use when" line written in the words a leader would use when asking,
// which makes the note easy to match against real questions.
// =============================================================================

const LLM_MODEL = $env.LLM_MODEL || 'llama3.2';

const DISTILLER_SYSTEM = [
  'You turn an executive-coaching session into a dense framework note for a coaching knowledge base.',
  'Build the note only from ideas the coach actually expressed in the transcript.',
  '',
  'Write plain text in exactly this layout:',
  'Framework: <the name the coach used, or a short descriptive name>',
  'Use when: <the leadership situations it applies to, in the plain words a leader would use when asking for help>',
  'Core idea: <two or three sentences>',
  'How to apply: <three to five short numbered steps>',
  'Key question: <the diagnostic question or signature line the coach used>',
  '',
  'Keep the whole note under 900 characters.',
].join('\n');

return $input.all().map((item) => {
  const s = item.json;
  const transcriptText = (s.transcript ?? [])
    .map((t) => `${t.speaker}: ${String(t.text ?? '').trim()}`)
    .join('\n');

  return {
    json: {
      ...s,
      distiller_request: {
        model: LLM_MODEL,
        stream: false,
        options: { temperature: 0.2 },
        messages: [
          { role: 'system', content: DISTILLER_SYSTEM },
          {
            role: 'user',
            content: `Session ${s.session_id} - "${s.title}"\nClassifier summary: ${s.summary}\n\nFull transcript:\n${transcriptText}`,
          },
        ],
      },
    },
  };
});

// =============================================================================
// Node: "Dual-Stream Parser"         (Code node - Run Once for All Items)
// -----------------------------------------------------------------------------
// Input : responses of "Framework Distiller (LLM)", paired with the approved
//         sessions from "Prepare Framework Distillation".
// Output: ONE item per chunk to embed, for both streams:
//
//   Stream 1  framework     dense conceptual takeaway of the coaching framework
//                           (LLM-distilled; extractive fallback if the LLM
//                           output is empty/unusable)
//   Stream 2  voice_sample  the coach's verbatim turns only, in 400-700 char
//                           chunks. Sentence boundaries are never cut, turns
//                           are separated by a blank line to keep the rhythm.
// =============================================================================

const MIN_CHARS = 400;
const MAX_CHARS = 700;
const IDEAL_CHARS = 550;

// ---------------------------------------------------------------------------
// Speaker filtering
// ---------------------------------------------------------------------------
/** The coach = the GenX team member who speaks the most in the session. */
function identifyCoach(session) {
  const team = new Set((session.participants ?? []).filter((p) => p.is_team_member).map((p) => p.name));
  const words = {};
  for (const t of session.transcript ?? []) {
    words[t.speaker] = (words[t.speaker] ?? 0) + String(t.text ?? '').split(/\s+/).length;
  }
  const ranked = Object.entries(words).sort((a, b) => b[1] - a[1]).map(([name]) => name);
  return ranked.find((n) => team.has(n)) ?? ranked.find((n) => /^dr\.?\s/i.test(n)) ?? ranked[0];
}

const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

// ---------------------------------------------------------------------------
// Sentence splitting (protects "Dr.", "e.g." etc. from false splits)
// ---------------------------------------------------------------------------
const ABBREV = /\b(Dr|Mr|Mrs|Ms|Prof|Sr|Jr|vs|etc|e\.g|i\.e)\./gi;
function splitSentences(text) {
  const protectedText = text.replace(ABBREV, (m) => m.replace(/\./g, '\u0000'));
  return protectedText
    .split(/(?<=[.!?]['"’”]?)\s+(?=['"‘“]?[A-Z0-9])/)
    .map((s) => s.replace(/\u0000/g, '.').trim())
    .filter(Boolean)
    .flatMap((s) => (s.length <= MAX_CHARS ? [s] : hardSplit(s)));
}
/** Only for a single sentence longer than MAX_CHARS: cut at word boundaries. */
function hardSplit(s) {
  const parts = [];
  let rest = s;
  while (rest.length > MAX_CHARS) {
    let cut = rest.lastIndexOf(' ', MAX_CHARS);
    if (cut < MIN_CHARS) cut = MAX_CHARS;
    parts.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) parts.push(rest);
  return parts;
}

// ---------------------------------------------------------------------------
// Voice chunking: optimal partition of sentence units into 400-700 char chunks
// ---------------------------------------------------------------------------
/** units: [{ text, turnIdx, timestamp }] -> joined text (blank line between turns) */
function joinUnits(units) {
  let out = '';
  units.forEach((u, k) => {
    if (k > 0) out += u.turnIdx === units[k - 1].turnIdx ? ' ' : '\n\n';
    out += u.text;
  });
  return out;
}

function chunkCost(len) {
  if (len >= MIN_CHARS && len <= MAX_CHARS) return ((len - IDEAL_CHARS) / 100) ** 2;
  const miss = len < MIN_CHARS ? MIN_CHARS - len : len - MAX_CHARS;
  return 1e6 + miss * miss; // out-of-bounds chunks only if nothing else is possible
}

/** Dynamic programming over sentence boundaries -> minimal total cost. */
function partition(units) {
  const n = units.length;
  const best = new Array(n + 1).fill(Infinity);
  const prev = new Array(n + 1).fill(-1);
  best[0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let j = i - 1; j >= 0; j--) {
      const len = joinUnits(units.slice(j, i)).length;
      if (len > MAX_CHARS && i - j > 1) break; // longer windows only get longer
      const c = best[j] + chunkCost(len);
      if (c < best[i]) { best[i] = c; prev[i] = j; }
    }
  }
  const ranges = [];
  for (let i = n; i > 0; i = prev[i]) ranges.unshift([prev[i], i]);
  return ranges;
}

/**
 * If a chunk is still below MIN_CHARS (total coach text did not divide cleanly
 * at sentence boundaries), borrow whole neighbouring sentences as overlap:
 * first the preceding ones, then the following ones, never exceeding MAX_CHARS.
 */
function applyOverlap(units, ranges) {
  const len = (s, e) => joinUnits(units.slice(s, e)).length;
  return ranges.map(([start, end]) => {
    let s = start;
    let e = end;
    while (s > 0 && len(s, e) < MIN_CHARS && len(s - 1, e) <= MAX_CHARS) s--;
    while (e < units.length && len(s, e) < MIN_CHARS && len(s, e + 1) <= MAX_CHARS) e++;
    return { start: s, end: e, overlap_units: (start - s) + (e - end) };
  });
}

function buildVoiceChunks(session, coach) {
  const turns = (session.transcript ?? [])
    .map((t, idx) => ({ ...t, idx }))
    .filter((t) => t.speaker === coach && clean(t.text));

  const units = turns.flatMap((t) =>
    splitSentences(clean(t.text)).map((text) => ({ text, turnIdx: t.idx, timestamp: t.timestamp })));
  if (units.length === 0) return [];

  return applyOverlap(units, partition(units)).map(({ start, end, overlap_units }) => {
    const slice = units.slice(start, end);
    const content = joinUnits(slice);
    return {
      content,
      speaker: coach,
      timestamps: [...new Set(slice.map((u) => u.timestamp))],
      turn_count: new Set(slice.map((u) => u.turnIdx)).size,
      char_count: content.length,
      within_bounds: content.length >= MIN_CHARS && content.length <= MAX_CHARS,
      overlap_sentences: overlap_units,
    };
  });
}

// ---------------------------------------------------------------------------
// Framework stream
// ---------------------------------------------------------------------------
function cleanDistilled(text) {
  return String(text ?? '')
    .replace(/\*\*|__|`/g, '')
    .replace(/^#+\s*/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function frameworkName(text) {
  const fromNote = text.match(/^\s*Framework:\s*(.+)$/im);
  if (fromNote) return fromNote[1].trim().replace(/[."]+$/, '');
  const fromTalk = text.match(/(?:framework called|we run the|we use the)\s+(?:the\s+)?([A-Z][\w-]*(?:\s+(?:[A-Z][\w-]*|and|with|of)){0,5})/);
  return fromTalk ? fromTalk[1].trim() : null;
}

/** Fallback if the LLM output is unusable: stitch the coach's teaching turns. */
function extractiveFramework(session, coach) {
  const coachTurns = (session.transcript ?? []).filter((t) => t.speaker === coach).map((t) => clean(t.text));
  const clientTurns = (session.transcript ?? []).filter((t) => t.speaker !== coach).map((t) => clean(t.text));
  const name = frameworkName(coachTurns.join(' ')) ?? `${session.title} coaching approach`;
  // Client's opening problem, minus a leading greeting sentence ("Hi Dr. Sara.")
  const problem = splitSentences(clientTurns[0] ?? session.summary ?? '')
    .filter((s, idx) => !(idx === 0 && /^(hi|hey|hello)\b/i.test(s))).join(' ');
  const keyQuestion = coachTurns.flatMap(splitSentences).find((s) => s.includes('?'))
    ?? coachTurns[coachTurns.length - 1] ?? '';
  return [
    `Framework: ${name}`,
    `Use when: ${problem}`,
    `Core idea: ${coachTurns.slice(0, 2).join(' ')}`,
    `Key question: ${keyQuestion}`,
  ].join('\n');
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
const out = [];
$input.all().forEach((item, i) => {
  const session = $('Prepare Framework Distillation').itemMatching(i).json;
  const coach = identifyCoach(session);

  const distilled = cleanDistilled(item.json?.message?.content);
  const useLlm = !item.json?.error && distilled.length >= 120 && /framework:/i.test(distilled);
  const frameworkText = useLlm ? distilled : extractiveFramework(session, coach);

  const shared = {
    title: session.title,
    session_date: session.source_created_at,
    coach,
    client: (session.participants ?? []).filter((p) => !p.is_team_member).map((p) => p.name),
    meeting_type: session.meeting_type,
    classifier_confidence: session.confidence_score,
    classifier_summary: session.summary,
  };

  // Stream 1: framework
  const frameworks = [{
    content: frameworkText,
    metadata: { ...shared, framework_name: frameworkName(frameworkText), source: useLlm ? 'llm_distilled' : 'extractive_fallback', char_count: frameworkText.length },
  }];

  // Stream 2: voice_sample
  const voices = buildVoiceChunks(session, coach).map(({ content, ...meta }) => ({
    content,
    metadata: { ...shared, ...meta },
  }));

  const emit = (stream_type, arr) => arr.forEach((c, idx) => out.push({
    json: {
      session_id: session.session_id,
      stream_type,
      chunk_index: idx,
      chunk_total: arr.length,
      content: c.content,
      metadata: c.metadata,
    },
    pairedItem: { item: i },
  }));

  emit('framework', frameworks);
  emit('voice_sample', voices);
});

return out;

// =============================================================================
// Node: "Prepare Vector Row"         (Code node - Run Once for All Items)
// -----------------------------------------------------------------------------
// Pairs each Ollama /api/embed response with its chunk and validates the
// vector before it touches the database: right dimension, finite numbers.
// A bad embedding stops the run loudly instead of silently corrupting the vault.
// =============================================================================

const EXPECTED_DIM = 1024; // bge-m3; must match vector(1024) in init.sql

return $input.all().map((item, i) => {
  const chunk = $('Dual-Stream Parser').itemMatching(i).json;
  const vec = item.json?.embeddings?.[0] ?? item.json?.embedding;

  if (!Array.isArray(vec) || vec.length !== EXPECTED_DIM || !vec.every(Number.isFinite)) {
    throw new Error(
      `Embedding for ${chunk.session_id}/${chunk.stream_type}#${chunk.chunk_index} is invalid ` +
      `(got ${Array.isArray(vec) ? vec.length : typeof vec} dims, expected ${EXPECTED_DIM}). ` +
      'Check that EMBED_MODEL is bge-m3 and Ollama is reachable.',
    );
  }

  return {
    json: {
      session_id: chunk.session_id,
      stream_type: chunk.stream_type,
      chunk_index: chunk.chunk_index,
      chunk_total: chunk.chunk_total,
      content: chunk.content,
      metadata_json: JSON.stringify({ ...chunk.metadata, embed_model: item.json?.model ?? 'bge-m3' }),
      embedding_literal: `[${vec.join(',')}]`, // pgvector text format
    },
    pairedItem: { item: i },
  };
});
